const { chatInput, sessionId } = $('Edit Fields').first().json;

let contextData = {};
let analytics = {};
let fetchError = false;
try {
  const res = $('Fetch Admin Context').first().json;
  contextData = res.context || {};
  analytics = res.analytics || {};
} catch {
  fetchError = true;
}

const briefing = analytics.daily_briefing || '';
const healthScores = analytics.health_score_by_villa || {};
const occupancy = analytics.occupancy_by_villa || {};
const adminAlerts = analytics.admin_alerts || [];

const systemMessage = `Tu es Kayvibot Admin, le copilote intelligent de l'équipe Kayvila. Tu parles français, tu es stratégique, proactif et orienté action.

TON RÔLE
- Analyser la performance globale (occupation, revenus, santé OTA)
- Détecter les anomalies et problèmes urgents
- Proposer des actions concrètes (blocage dates, création tâches, relance soumissions)
- Comparer les villas entre elles (benchmark interne)
- Générer des briefings quotidiens actionnables

RÈGLES
- Répondre en JSON : { "response": "...", "action": "SHOW_STATS"|"CREATE_TASK"|"BLOCK_DATE"|"UPDATE_BOOKING"|"UPDATE_TASK_STATUS"|"UPDATE_SUBMISSION_STATUS"|"COMPLETE_TASK", "action_data": {...}, "suggested_prompts": [...] }
- Pour les actions destructives, TOUJOURS demander confirmation explicite avant exécution
- Utiliser UNIQUEMENT les données du contexte — ne rien inventer
- Prioriser les alertes par criticité

═════════════════════════════
CONTEXTE TEMPS RÉEL :
📊 BRIEFING : ${briefing}
🏥 SANTÉ VILLAS : ${JSON.stringify(healthScores)}
📈 OCCUPATION : ${JSON.stringify(occupancy)}
⚠️ ALERTES : ${JSON.stringify(adminAlerts)}
📋 DONNÉES COMPLÈTES : ${JSON.stringify(contextData)}
═════════════════════════════`;

return {
  json: { chatInput, sessionId, systemMessage, contextData, fetchError }
};

const aiResponse =
  $input.first().json.output ||
  $input.first().json.message?.content ||
  $input.first().json.text ||
  '';

let response = aiResponse;
let action = 'SHOW_STATS';
let actionData = {};
let suggestedPrompts = [];
let strategicAlert = null;

try {
  const parsed = typeof aiResponse === 'string' ? JSON.parse(aiResponse) : aiResponse;
  if (parsed && typeof parsed === 'object') {
    response = parsed.response || parsed.reply || parsed.message || aiResponse;
    action = parsed.action || 'SHOW_STATS';
    actionData = parsed.action_data || {};
    suggestedPrompts = Array.isArray(parsed.suggested_prompts) ? parsed.suggested_prompts : [];
    strategicAlert = parsed.strategic_alert || null;
  }
} catch {}

return {
  json: { response, action, action_data: actionData, suggested_prompts: suggestedPrompts, strategic_alert: strategicAlert }
};
